	assert values.length == volumes.length;

	double[][] A = new double[values.length + 1][capacity + 1];

	for(int k = 1; k <= values.length; k++) {
	    for(int l = 1; l <= capacity; l++) {
    		if(volumes[k - 1] > l) {
    		    A[k][l] = A[k - 1][l];
    		} else if(A[k - 1][l - volumes[k - 1]] + values[k-1] > A[k - 1][l]) {
