Student code:
```java
public double knapSack(double[] values, int[] volumes, int capacity) {
        assert values.length == volumes.length;
        int n = values.length;
        if (n <= 0 || capacity <= 0) {
            return 0;
        }

        double[][] matrix = new double[n + 1][capacity + 1];
        for (int j = 0; j <= capacity; j++) {
            matrix[0][j] = 0;
        }

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= capacity; j++) { 
                if (volumes[i - 1] > j) {
                    matrix[i][j] = matrix[i - 1][j];
                } else {
                    matrix[i][j] = Math.max(
                      matrix[i - 1][j], 
                      matrix[i - 1][j - volumes[i - 1]] + values[i - 1]);
                }
            }
        }
        return matrix[n][capacity];
    }

