public double knapSack(double[] values, int[] volumes, int capacity) 
{
    assert values.length == volumes.length;
    double[][] table = new double[volumes.length+1][capacity+1];
    if(capacity == 0)
    {
        return 0.0;
    }
    for (int i = 0; i < volumes.length+1; i++)
    {
        for (int j = 0; j < capacity+1; j++)
        {
            table[i][0] = 0;
            table[0][j] = 0;
        }
    }

    for (int k = 1; k < volumes.length+1; k++)
    {
        for (int l = 1; l < capacity+1; l++)
        {
            if(volumes[k-1] > l)
            {
                table[k][l] = table[k-1][l];
            }
            else
            {
                if(table[k-1][l-volumes[k-1]] + values[k-1] > table[k-1][l])
                {
                    table[k][l] = table[k-1][l-volumes[k-1]] + values[k-1];
                }
                else
                {
                    table[k][l] = table[k-1][l];
                }
            }
        }
    }
    return table[volumes.length][capacity];
}

