public double knapSack(double[] values, int[] volumes, int capacity) {
    assert values.length == volumes.length;

    if (values.length <= 0 || capacity <= 0) {
        return 0.0;
    }

    double[][] m = new double[values.length + 1][capacity + 1];
    for (int j = 0; j <= capacity; j++) {
        m[0][j] = 0.0;
    }

    for (int i = 1; i <= values.length; i++) {
        for (int j = 0; j <= capacity; j++) { // <-- changed from j=1 to j=0
            if (volumes[i - 1] > j) {
                m[i][j] = m[i - 1][j];
            } else {
                m[i][j] = Math.max(
                  m[i - 1][j], 
                  m[i - 1][j - volumes[i - 1]] + values[i - 1]);
            }
        }
    }
    return m[values.length][capacity];
}

